        if dry_run:
            spec["dry_run"] = True
            return Plan(self._call("command", spec=spec))
        return self._command(spec)

    def move_at(self, velocity, joints=None, ee=None, frame="world", accel=None, max_travel=None, duration=None,
                **common):
